begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values('3a000000-0000-4000-8000-000000000001','qol-scale@example.test','{}'),('3a000000-0000-4000-8000-000000000002','qol-scale-inactive@example.test','{}'),('3a000000-0000-4000-8000-000000000003','qol-scale-admin@example.test','{}');
update public.profiles set is_active=true where id in ('3a000000-0000-4000-8000-000000000001','3a000000-0000-4000-8000-000000000002','3a000000-0000-4000-8000-000000000003');
insert into public.user_roles(user_id,role) values('3a000000-0000-4000-8000-000000000001','STAFF'),('3a000000-0000-4000-8000-000000000002','STAFF'),('3a000000-0000-4000-8000-000000000003','ADMIN');
update public.profiles set is_active=false where id='3a000000-0000-4000-8000-000000000002';
create temp table fx(k text primary key,id uuid);grant all on fx to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"3a000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into fx select 'client',id from public.save_client(auth.uid(),null,null,'Scale','Family',null,null,'EMAIL',null,null);
insert into fx select 'pet',id from public.save_patient(null,(select id from fx where k='client'),null,'Scale dog','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
insert into fx select 'other',id from public.save_patient(null,(select id from fx where k='client'),null,'Other dog','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
-- Draft may be partial; total stays unknown until every category is scored.
select lives_ok($$select public.save_patient_qol_scale('3b000000-0000-4000-8000-000000000001',(select id from fx where k='pet'),null,now(),'Dr. Synthetic',5,null,6,null,null,null,null,'Guarding','','','','','','','Partial draft')$$,'Create partial scale draft');
select lives_ok($$select public.save_patient_qol_scale('3b000000-0000-4000-8000-000000000001',(select id from fx where k='pet'),null,now(),'Dr. Synthetic',5,null,6,null,null,null,null,'Guarding','','','','','','','Partial draft')$$,'Exact creation retry is idempotent');
select is((select count(*) from public.patient_qol_scale_assessments),1::bigint,'Retry creates no duplicate assessment');
select is((select total from public.patient_qol_scale_assessments where id='3b000000-0000-4000-8000-000000000001'),null::smallint,'Partial draft has no total');
select throws_ok($$select public.sign_patient_qol_scale('3b000000-0000-4000-8000-000000000001',1)$$,'23514','Score all seven categories before signing','Signing requires all seven categories');
-- Range and integrity constraints.
select throws_ok($$select public.save_patient_qol_scale(gen_random_uuid(),(select id from fx where k='pet'),null,now(),'Dr. Synthetic',11,5,5,5,5,5,5,'','','','','','','','')$$,'23514','Each category score must be a whole number from 0 to 10','Score above 10 rejected');
select throws_ok($$select public.save_patient_qol_scale(gen_random_uuid(),(select id from fx where k='pet'),null,now(),'Dr. Synthetic',5,5,5,5,5,5,-1,'','','','','','','','')$$,'23514',null,'Negative score rejected');
select throws_ok($$select public.save_patient_qol_scale(gen_random_uuid(),(select id from fx where k='pet'),null,'infinity','Dr. Synthetic',5,5,5,5,5,5,5,'','','','','','','','')$$,'23514',null,'Nonfinite assessment time rejected');
select throws_ok($$select public.save_patient_qol_scale(gen_random_uuid(),(select id from fx where k='pet'),null,now()+interval '1 day','Dr. Synthetic',5,5,5,5,5,5,5,'','','','','','','','')$$,'23514',null,'Future assessment time rejected');
select throws_ok($$select public.save_patient_qol_scale(gen_random_uuid(),(select id from fx where k='pet'),null,now(),'  ',5,5,5,5,5,5,5,'','','','','','','','')$$,'23514',null,'Assessor required');
select throws_ok($$select public.save_patient_qol_scale(gen_random_uuid(),(select id from fx where k='pet'),null,now(),'Dr. Synthetic',5,5,5,5,5,5,5,repeat('x',2001),'','','','','','','')$$,'23514',null,'Category note length bounded');
select throws_ok($$select public.save_patient_qol_scale('3b000000-0000-4000-8000-000000000001',(select id from fx where k='other'),1,now(),'Dr. Synthetic',5,5,5,5,5,5,5,'','','','','','','','')$$,'23514','Patient does not match assessment','Cannot reparent assessment');
select throws_ok($$select public.save_patient_qol_scale('3b000000-0000-4000-8000-000000000001',(select id from fx where k='pet'),0,now(),'Dr. Synthetic',5,5,5,5,5,5,5,'','','','','','','','')$$,'40001',null,'Stale edit rejected');
-- Complete, sign and verify total.
select lives_ok($$select public.save_patient_qol_scale('3b000000-0000-4000-8000-000000000001',(select id from fx where k='pet'),1,now(),'Dr. Synthetic',5,7,6,8,4,3,2,'Guarding','','','','','Slow on stairs','','Complete')$$,'Complete all categories');
select is((select total from public.patient_qol_scale_assessments where id='3b000000-0000-4000-8000-000000000001'),35::smallint,'Total is the sum of seven categories');
select is((select version from public.patient_qol_scale_assessments where id='3b000000-0000-4000-8000-000000000001'),2,'Draft revision increments');
select lives_ok($$select public.sign_patient_qol_scale('3b000000-0000-4000-8000-000000000001',2)$$,'Sign complete assessment');
select lives_ok($$select public.sign_patient_qol_scale('3b000000-0000-4000-8000-000000000001',2)$$,'Signing retry is idempotent');
select is((select signed_by from public.patient_qol_scale_assessments where id='3b000000-0000-4000-8000-000000000001'),auth.uid(),'Signer derives from session');
-- Immutability.
select throws_ok($$select public.save_patient_qol_scale('3b000000-0000-4000-8000-000000000001',(select id from fx where k='pet'),3,now(),'Dr. Synthetic',10,10,10,10,10,10,10,'','','','','','','','')$$,'23514',null,'Signed assessment cannot be rewritten');
select throws_ok($$update public.patient_qol_scale_assessments set hurt=0$$,'42501',null,'Direct score update denied');
select throws_ok($$delete from public.patient_qol_scale_assessments$$,'42501',null,'Direct delete denied');
select throws_ok($$insert into public.patient_qol_scale_assessments(id,pet_id,assessed_at,assessor,created_by,updated_by) values(gen_random_uuid(),(select id from fx where k='pet'),now(),'x',auth.uid(),auth.uid())$$,'42501',null,'Direct insert denied');
select lives_ok($$select public.add_patient_qol_scale_addendum('3b000000-0000-4000-8000-000000000002','3b000000-0000-4000-8000-000000000001','Mobility note should read slow on the back steps')$$,'Append signed-assessment addendum');
select lives_ok($$select public.add_patient_qol_scale_addendum('3b000000-0000-4000-8000-000000000002','3b000000-0000-4000-8000-000000000001','Mobility note should read slow on the back steps')$$,'Addendum retry is idempotent');
select throws_ok($$select public.add_patient_qol_scale_addendum('3b000000-0000-4000-8000-000000000002','3b000000-0000-4000-8000-000000000001','Changed')$$,'23514','Addendum identifier already used','Changed addendum replay rejected');
select lives_ok($$select public.save_patient_qol_scale('3b000000-0000-4000-8000-000000000003',(select id from fx where k='pet'),null,now(),'Dr. Synthetic',5,5,5,5,5,5,5,'','','','','','','','')$$,'Second draft');
select throws_ok($$select public.add_patient_qol_scale_addendum(gen_random_uuid(),'3b000000-0000-4000-8000-000000000003','Too early')$$,'23514','Addenda require a signed assessment','Draft cannot take addenda');
select throws_ok($$update public.patient_qol_scale_addenda set content='erase'$$,'42501',null,'Direct addendum rewrite denied');
reset role;
select throws_ok($$update public.patient_qol_scale_assessments set hurt=0 where id='3b000000-0000-4000-8000-000000000001'$$,'23514','Signed quality-of-life assessments are immutable; add an addendum','Signed row immutable below the RPC layer');
select throws_ok($$delete from public.patient_qol_scale_addenda$$,'23514',null,'Addendum history cannot be deleted below the RPC layer');
select throws_ok($$update public.patient_qol_scale_assessments set hurt=null,status='signed' where id='3b000000-0000-4000-8000-000000000003'$$,'23514',null,'Missing category blocks signing below the RPC layer');
select throws_ok($$update public.patient_qol_scale_assessments set hurt=11 where id='3b000000-0000-4000-8000-000000000003'$$,'23514',null,'Range CHECK enforced below the RPC layer');
set local role authenticated;
-- Reference setting: disabled by default, administrator only, requires wording and review note when enabled.
select is((select row(enabled,reference_total) from public.qol_scale_reference_settings)::text,'(f,)','Reference disabled with no threshold by default');
select throws_ok($$select public.save_qol_scale_reference(1,true,35,'Configured reference','Pending review')$$,'42501',null,'Staff cannot configure reference');
select set_config('request.jwt.claims','{"sub":"3a000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select throws_ok($$select public.save_qol_scale_reference(1,true,null,'Configured reference','Pending review')$$,'23514',null,'Enabled reference requires a total');
select throws_ok($$select public.save_qol_scale_reference(1,true,71,'Configured reference','Pending review')$$,'23514',null,'Reference total bounded to 0-70');
select throws_ok($$select public.save_qol_scale_reference(1,true,35,'Configured reference','')$$,'23514',null,'Enabled reference requires a review note');
select lives_ok($$select public.save_qol_scale_reference(1,true,35,'Synthetic configured reference','Synthetic test entry')$$,'Administrator configures reference');
select lives_ok($$select public.save_qol_scale_reference(1,true,35,'Synthetic configured reference','Synthetic test entry')$$,'Reference save replay is idempotent');
select throws_ok($$select public.save_qol_scale_reference(1,false,null,'','')$$,'40001',null,'Stale reference save rejected');
select throws_ok($$update public.qol_scale_reference_settings set enabled=false$$,'42501',null,'Direct setting update denied');
select set_config('request.jwt.claims','{"sub":"3a000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is((select count(*) from public.patient_qol_scale_assessments),0::bigint,'Inactive staff cannot read assessments');
select throws_ok($$select public.sign_patient_qol_scale('3b000000-0000-4000-8000-000000000003',1)$$,'42501','Active staff access required','Inactive staff cannot sign');
set local role anon;
select throws_ok($$select * from public.patient_qol_scale_assessments$$,'42501',null,'Anonymous reads denied');
select throws_ok($$select public.save_patient_qol_scale(gen_random_uuid(),gen_random_uuid(),null,now(),'x',1,1,1,1,1,1,1,'','','','','','','','')$$,'42501',null,'Anonymous RPC denied');
reset role;
select ok(exists(select 1 from public.audit_logs where table_name='patient_qol_scale_assessments' and user_id='3a000000-0000-4000-8000-000000000001'),'Assessments audited');
select ok(exists(select 1 from public.audit_logs where table_name='qol_scale_reference_settings' and user_id='3a000000-0000-4000-8000-000000000003'),'Reference setting changes audited');
select * from finish();
rollback;
